python - <<'PY'
import sys,math,cv2,numpy as np
sys.path.insert(0,'/app/output');import gen
P=gen.paths();target=(cv2.imread('/app/target.png',0)<100);scale=3
for deg in range(20,41,2):
 hi=np.zeros((1024*scale,1024*scale),np.uint8);e=np.array([math.cos(math.radians(deg)),-math.sin(math.radians(deg))])*(.004/gen.PX_M/2)
 for path in P:
  for p in path:
   a=np.rint((p-e)*scale).astype(int);b=np.rint((p+e)*scale).astype(int);cv2.line(hi,tuple(a),tuple(b),255,round(.0004/gen.PX_M*scale))
 mask=cv2.resize(hi,(1024,1024),interpolation=cv2.INTER_AREA)>=128
 best=(-1,None)
 for dx in range(-2,3):
  for dy in range(-2,3):
   M=np.float32([[1,0,dx],[0,1,dy]])
   mm=cv2.warpAffine(mask.astype('uint8'),M,(1024,1024))>0
   i=(mm&target).sum();u=(mm|target).sum();score=i/u
   if score>best[0]:best=(score,(dx,dy,i/mm.sum(),i/target.sum()))
 print(deg,best)
